Q: How to use XAMPP MySQL database with my Java Application? A: <p>You can do it like this -  </p>

<ol>
<li><p><strong>To connect to the Database</strong>     </p>

<pre><code> import java.sql.Connection;
 import java.sql.DriverManager;
 import java.sql.Statement;
 import java.sql.Connection;
 import java.sql.DriverManager;
 import java.sql.ResultSet;
 import java.sql.SQLException;
 import java.sql.Statement;

 Statement statement;

 //function to connect to the xampp server      
 public void DatabaseConnect(){
     try {
        Connection conn= DriverManager.getConnection("jdbc:mysql://localhost/javafx","root",""); 
        /*here javafx is the name of the database and root is the username of
         your xampp server and the field which is blank is for password. 
         Because I haven't set the password. I have left it blank*/
         statement = conn.createStatement();
         System.out.print("Database Connected");
     } catch (Exception e) {
         System.out.print("Database Not Connected");
     }
  }
</code></pre></li>
</ol>

<p><strong>Below given are the various operations you can perform after connecting to the database.</strong></p>

<pre><code>//for inserting data
public void insert(){
    try{
        String insertquery = "INSERT INTO `tablename`(`field1`, `field2`) VALUES ('value1', 'value2'";
        statement.executeUpdate(insertquery);
        System.out.print("Inserted");
    } catch(Exception e){
        System.out.print("Not Inserted");
    }
}

 //for viewing data
 public void view(){
    try {
        String insertquery = "select * from `table_name` where field = 'value1'";
        ResultSet result = statement.executeQuery(insertquery);
        if(result.next()){
            System.out.println("Value " + result.getString(2));
            System.out.println("Value " + result.getString(3));
        }
    } catch (SQLException ex) {
        System.out.println("Problem To Show Data");
    }
 }

 //to update data
 public void update(){
    try {
        String insertquery = "UPDATE `table_name` set `field`='value',`field2`='value2' WHERE field = 'value'";
        statement.executeUpdate(insertquery);
        System.out.println("Updated")
    } catch (SQLException ex) {
        System.out.println(ex.getMessage());
    }
 }

//to delete data
public void delete(){
     try {
        String insertquery = "DELETE FROM `table_name` WHERE field = 'value'";
        statement.executeUpdate(insertquery);
        System.out.println("Deleted");
    } catch (SQLException ex) {
        System.out.println(ex.getMessage());
    }
 }
</code></pre>

<p>Also, don't forget to add the <code>JAR</code> file in your <strong>system library</strong>. For this example, I have used <code>mysql-connector-java-5.1.46</code></p>

Q: Tabs background and font color change when click A: <p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>$(".tab").click(function() {
  $(".tab").removeClass('selected')
  $(this).addClass('selected')
})
$(".tab").hover(function() {
  $(".tab").removeClass('selected')
  $(this).addClass('selected')
})</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>.tab {
  width: 60px;
  height: 60px;
  background: #3be9a6;
  margin: 20px;
  display: inline-block;
  float: left
}
.selected {
  background: #3b6;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://ajax.googleapis.com/ajax/libs/jquery/2.1.1/jquery.min.js"&gt;&lt;/script&gt;
